import { Component } from '@angular/core';

@Component({
  selector: 'app-applications',
  imports: [],
  templateUrl: './applications.html',
  styleUrl: './applications.css',
})
export class Applications {}

import {Component, OnDestroy, OnInit} from '@angular/core';
import {CommonModule} from '@angular/common';
import {Observable, Subscription, catchError, finalize, of} from 'rxjs';
import {ApplicationService} from '../../../services/services/Application-service/application-service';
import {PagedResponse} from '../../../models/Dto/PagedResponse';
import {ApplicationResponse} from '../../../models/Dto/Application/ApplicationResponse';
import {AdminApplicationStatsResponse} from '../../../models/Dto/Application/AdminApplicationStatsResponse';
import {ApplicationStatus} from '../../../models/Enum/ApplicationStatus';

@Component({
  selector: 'app-applications',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './applications.html',
  styleUrl: './applications.css',
})
export class Applications implements OnInit, OnDestroy {
  applicationsResponse: PagedResponse<ApplicationResponse> | null = null;
  stats$!: Observable<AdminApplicationStatsResponse>;
  loading = true;

  page = 0;
  size = 10;

  private readonly subscriptions = new Subscription();

  constructor(private applicationService: ApplicationService) {}

  ngOnInit() {
    this.applicationsResponse = this.buildEmptyResponse();
    this.stats$ = this.applicationService.getAdminApplicationStats();
    this.fetchApplications();
  }

  ngOnDestroy() {
    this.subscriptions.unsubscribe();
  }

  changePage(newPage: number) {
    this.page = newPage;
    this.fetchApplications();
  }

  downloadCv(cvFilePath?: string | null) {
    if (!cvFilePath) {
      return;
    }

    window.open(cvFilePath, '_blank');
  }

  protected readonly ApplicationStatus = ApplicationStatus;

  private fetchApplications() {
    this.loading = true;
    const sub = this.applicationService
      .getAdminApplications(this.page, this.size)
      .pipe(
        catchError(() => of(this.buildEmptyResponse())),
        finalize(() => {
          this.loading = false;
        })
      )
      .subscribe(response => {
        this.applicationsResponse = response;
      });

    this.subscriptions.add(sub);
  }

  private buildEmptyResponse(): PagedResponse<ApplicationResponse> {
    return {
      content: [],
      totalElements: 0,
      totalPages: 1,
      number: this.page,
      size: this.size,
      first: this.page === 0,
      last: true,
    };
  }
}
